    "id": "usp-sp-2025-031",
    "number": 31,
    "stem": "Que medida de ocorrência ou de associação está representada na última coluna da tabela a seguir, no contexto do estudo descrito?\n\nFoi realizado um estudo transversal de base populacional na cidade de Pelotas, no sul do Brasil. Todos os indivíduos com idades entre 10 e 19 anos de idade que residiam nas moradias selecionadas foram convidados a participar do estudo. Para identificar depressão, foi aplicado o instrumento PHQ-9 (Patient Health Questionnaire – 9). Foram avaliados 359 adolescentes do sexo masculino e 384 do sexo feminino, dos quais 50 meninos e 76 meninas foram diagnosticados com depressão, conforme tabela a seguir:\n\n• Sexo Masculino: Depressão (+) = 50 | Depressão (-) = 309 | Coluna ??? = 13,9%\n• Sexo Feminino: Depressão (+) = 76 | Depressão (-) = 308 | Coluna ??? = 19,8%\n• Total: Depressão (+) = 126 | Depressão (-) = 617 | Coluna ??? = 17,0%",
