    "id": "usp-sp-2025-054",
    "number": 54,
    "stem": "Mulher, 69 anos de idade, foi submetida à laparotomia exploradora para reconstrução de trânsito intestinal 6 meses após retossigmoidectomia com colostomia terminal devido à diverticulite aguda. No intraoperatório foi necessário realizar lise de aderências de intestino. O procedimento foi realizado sem intercorrências com duração de 6 horas e a paciente foi encaminhada para enfermaria. Desde o primeiro dia pós-operatório, estava deambulando. No terceiro dia pós-operatório, evoluiu com distensão abdominal e vômitos. Neste momento, foi realizada a passagem de sonda nasogástrica com saída de 900 mL. No sexto dia pós-operatório, manteve débito elevado pela sonda (> 1000 mL/dia). Ainda não evacuou e sem eliminação de gases. Ao exame físico, encontra-se em bom estado geral, FC de 80 bpm e PA de 130x80 mmHg, hidratada, abdome com ferida de bom aspecto, distendido, ruídos diminuídos e pouca dor à palpação profunda, sem sinais de irritação peritoneal. Dreno com débito seroso (média de 80 mL/dia).\n\n• Exames laboratoriais:\nHb: 10,1 g/dL\nHt: 31%\nLeucograma: 8.120/mm3\nCreatinina: 0,9 mg/dL\nUreia: 54 mg/dL\nPCR: 41 mg/L (prévio de dois dias atrás 81 mg/L)\n\nAssinale a principal hipótese diagnóstica para este caso.",
