    "number": 56,
    "stem": "Mulher, 43 anos de idade, foi admitida no Serviço de Emergência com dor abdominal há 6 dias. Refere que, desde o início do quadro, procurou duas vezes atendimento médico e foi liberada após analgesia e orientação de dieta. Tem diabetes melito e obesidade. Ao exame físico, encontra-se em regular estado geral; FC de 110 bpm; PA de 90x60 mmHg; FR de 18 ipm; ausculta torácica sem alterações; abdome: doloroso à palpação difusa com sinais de irritação peritoneal.\n\n• Exames laboratoriais:\nHb: 11,2g/dL\nHt: 35%\nLeucograma: 23.558/mm3\nPCR: 271 mg/L\nCreatinina: 2,1 mg/dL\nUreia: 70 mg/dL\npH: 7,31\nBE: - 8\nLactato: 39 mg/dL\n\nFoi realizada tomografia de abdome que evidenciou líquido livre na cavidade em todos os quadrantes, decorrente de apendicite aguda. Na sala de emergência, foi realizada reanimação volêmica com 1 L de cristaloide e iniciada noradrenalina. Qual é o melhor esquema de antibiótico para o caso apresentado?",
