    "number": 70,
    "stem": "Homem, 41 anos de idade, refere dor no hipogástrio há 48 horas, com piora progressiva. Nega febre ou vômitos. Teve duas evacuações com fezes amolecidas. Nega queixas urinárias. Sem comorbidades. Tem antecedente de cólica renal. Ao exame físico, encontra-se em bom estado geral, apresenta abdome doloroso à palpação profunda do hipogástrio e fossa ilíaca direita sem sinais de irritação peritoneal; sem outras alterações.\n\n• Exames laboratoriais:\nHb: 13,4 g/dL\nLeucograma: 12.332/mm3\nPCR: 29 mg/L\n\nO resultado da tomografia de abdome pode ser visualizado nas imagens a seguir:\n\nConsiderando a principal hipótese diagnóstica, qual é a conduta mais adequada?",
