    "number": 74,
    "stem": "Mulher, 54 anos de idade, apresenta queixa de perda de urina ao rir e tossir. Será submetida à correção da perda urinária com o material apresentado a seguir, que será introduzido conforme técnica, também apresentada a seguir:\n\nQual é o mecanismo responsável pelo tratamento da incontinência urinária?",
