    "id": "usp-sp-2025-075",
    "number": 75,
    "stem": "Mulher, 27 anos de idade, refere dor mamária que se inicia cerca de 15 dias antes da menstruação. A dor é bilateral e intensa, dificultando uso de vestimenta e a realização de atividade física. Faz uso de anti-inflamatórios e analgésicos, sem resultado adequado. Apresenta ciclos menstruais regulares com intervalo de 30 dias. Faz uso de preservativo como contraceptivo. O exame clínico realizado no décimo dia do ciclo menstrual, revela mamas simétricas, sem abaulamentos ou retrações e a palpação é de tecido fibroglandular sem nódulos ou espessamentos identificados. Qual é o tratamento mais eficiente para esta paciente?",
