    "id": "usp-sp-2025-102",
    "number": 102,
    "stem": "Você está de plantão na enfermaria de pediatria e há disponibilidade de 3 leitos para internação. Há um quarto compartilhado de enfermaria que comporta dois leitos com distância de 2 metros entre eles e um quarto de isolamento respiratório com um leito. No pronto-socorro infantil, três crianças com bronquiolite aguardam internação: Enzo com vírus sincicial respiratório; Miguel com parainfluenza 3 e Caio com Influenza A. Além de precaução padrão, assinale a alternativa que apresenta a melhor opção de alocação dessas crianças.",
