    "id": "usp-sp-2025-110",
    "number": 110,
    "stem": "Adolescente, 14 anos de idade, diabética, procura atendimento médico na Unidade Básica de Saúde devido à alteração nas unhas dos hálux direito e esquerdo. Refere que, há 3 meses, ambas as unhas se tornaram espessadas, amareladas, com perda de brilho, conforme imagem apresentada a seguir:\n\nAs alterações tiveram início pela porção distal da unha. Nega trauma local. Assinale a alternativa que apresenta a terapêutica mais adequada a ser instituída, considerando a principal hipótese diagnóstica.",
